script:
frappe.ui.form.on('Quotation', {
    quotation_to: function(frm) {
        if (frm.doc.quotation_to === 'Lead') {
            frm.set_value('naming_series', 'SAL-QTN-.YYYY.-');
        }
    },
    before_save: function(frm) {
        if (frm.doc.quotation_to === 'Lead') {
            frm.doc.naming_series = 'SAL-QTN-.YYYY.-';
        }
    }
});

frappe.ui.form.on('Lead', {
    refresh: function(frm) {
            if (frm.doc.customer) {
                        setTimeout(function() {
                                        frm.add_custom_button('View Customer', function() {
                                                            frappe.set_route('Form', 'Customer', frm.doc.customer);
                                                                            });
                                                                                        }, 500);
                                                                                                }
                                                                                                    }
                                                                                                    });

frappe.ui.form.on('Quotation', {
    quotation_to: function(frm) {
        toggle_lead_field(frm);
    },
    party_name: function(frm) {
        if (frm.doc.quotation_to == 'Lead' && frm.doc.party_name) {
            frappe.db.get_value('Lead', frm.doc.party_name, 'customer', function(r) {
                if (r && r.customer) {
                    frm.set_value('custom_customer', r.customer);
                }
            });
        } else if (frm.doc.quotation_to == 'Customer' && frm.doc.party_name) {
            frappe.db.get_value('Lead', {'customer': frm.doc.party_name}, 'name', function(r) {
                if (r && r.name) {
                    frm.set_value('custom_lead', r.name);
                }
            });
        } else if (frm.doc.quotation_to == 'Prospect' && frm.doc.party_name) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Prospect',
                    name: frm.doc.party_name
                },
                callback: function(r) {
                    if (r.message && r.message.leads && r.message.leads.length) {
                        let lead = r.message.leads[0].lead;
                        if (lead) frm.set_value('custom_lead', lead);
                    }
                }
            });
        }
    },
    refresh: function(frm) {
        toggle_lead_field(frm);

        if (frm.doc.quotation_to == 'Lead' && frm.doc.party_name && !frm.doc.custom_customer) {
            frappe.db.get_value('Lead', frm.doc.party_name, 'customer', function(r) {
                if (r && r.customer) {
                    frm.set_value('custom_customer', r.customer);
                }
            });
        } else if (frm.doc.quotation_to == 'Customer' && frm.doc.party_name && !frm.doc.custom_lead) {
            frappe.db.get_value('Lead', {'customer': frm.doc.party_name}, 'name', function(r) {
                if (r && r.name) {
                    frm.set_value('custom_lead', r.name);
                }
            });
        } else if (frm.doc.quotation_to == 'Prospect' && frm.doc.party_name && !frm.doc.custom_lead) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Prospect',
                    name: frm.doc.party_name
                },
                callback: function(r) {
                    if (r.message && r.message.leads && r.message.leads.length) {
                        let lead = r.message.leads[0].lead;
                        if (lead) frm.set_value('custom_lead', lead);
                    }
                }
            });
        }

        frm.add_custom_button(__('Create Customer'), function() {
            frappe.new_doc('Customer');
        }, __('Create'));
    }
});

function toggle_lead_field(frm) {
    let show = ['Prospect', 'Customer'].includes(frm.doc.quotation_to);
    frm.toggle_display('custom_lead', show);
}

frappe.ui.form.on('Lead', {
    refresh: function(frm) {
        if (frm.doc.__islocal) return;

        setTimeout(function() {
            frm.page.remove_inner_button(__('Customer'), __('Create'));
            frm.page.remove_inner_button(__('Opportunity'), __('Create'));
            frm.page.remove_inner_button(__('Quotation'), __('Create'));

            frm.add_custom_button(__('Create Quotation'), function() {
                frappe.model.open_mapped_doc({ method: 'kreatao_erpplus.overrides.quotation_patch.make_quotation_from_lead', frm: frm });
            }, __('Create'));

            frm.add_custom_button(__('Customer'), function() {
                frappe.model.open_mapped_doc({ method: 'kreatao_erpplus.overrides.quotation_patch.make_customer_from_lead', frm: frm });
            }, __('Create'));

            frm.add_custom_button(__('Contract'), function() {
                frappe.route_options = { party_type: 'Lead', party_name: frm.doc.name, custom_lead: frm.doc.name, custom_project_title: frm.doc.custom_project_title, custom_project_description: frm.doc.custom_project_description };
                frappe.new_doc('Contract');
            }, __('Create'));

            frm.add_custom_button(__('Project'), function() {
                let d = new frappe.ui.Dialog({
                    title: __('Create Project'),
                    fields: [
                        { fieldtype: 'Data', fieldname: 'project_name', label: __('Project Name'), reqd: 1, default: frm.doc.custom_project_title || frm.doc.company_name || frm.doc.lead_name },
                        { fieldtype: 'Data', fieldname: 'custom_project_title', label: __('Project Title'), default: frm.doc.custom_project_title },
                        { fieldtype: 'Long Text', fieldname: 'custom_project_detail', label: __('Project Description'), default: frm.doc.custom_project_description }
                    ],
                    primary_action_label: __('Create'),
                    primary_action: function(values) {
                        frappe.new_doc('Project', { project_name: values.project_name, custom_project_title: values.custom_project_title, custom_project_detail: values.custom_project_detail, custom_lead: frm.doc.name });
                        d.hide();
                    }
                });
                d.show();
            }, __('Create'));

            function create_from_lead_with_customer_check(doctype) {
                if (!frm.doc.customer) {
                    frappe.msgprint(__('Please create Customer first'));
                    return;
                }
                frappe.call({
                    method: 'kreatao_erpplus.overrides.quotation_patch.get_project_for_lead',
                    args: { lead: frm.doc.name },
                    callback: function(r) {
                        frappe.new_doc(doctype, {
                            custom_lead: frm.doc.name,
                            customer: frm.doc.customer,
                            project: r.message || null
                        });
                    }
                });
            }

            frm.add_custom_button(__('Client PO'), function() {
                create_from_lead_with_customer_check('Sales Order');
            }, __('Create'));

            frm.add_custom_button(__('Sales Invoice'), function() {
                create_from_lead_with_customer_check('Sales Invoice');
            }, __('Create'));
        }, 300);
    }
});
